import{_ as t}from"./chunks/grocery-delivery.B1Dpq_hn.js";import{_ as o,o as r,c as s,a5 as a}from"./chunks/framework.DukzBDYY.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md"}'),i={name:"getting-started/introduction.md"};function n(l,e,d,h,c,u){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Delivery Slots lets customers choose when their Craft Commerce order arrives, or when to collect it. It adds a time-slot picker to your checkout, and keeps each slot to the number of orders you can handle.</p><p><img src="'+t+'" alt="A grocery checkout with delivery or pickup, day buttons, two-hour slots and the order summary"></p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Slots per shipping method.</strong> Each Commerce shipping method, such as <em>Local delivery</em> or <em>Pick up in store</em>, gets its own time windows and days.</li><li><strong>Orders per slot.</strong> A slot closes when it’s full. While a customer pays, their slot is held so nobody else takes the last place.</li><li><strong>Ordering rules.</strong> A next-day cut-off, same-day slots, a minimum notice before a slot starts, and how many days ahead to show.</li><li><strong>Closed days.</strong> Public holidays and other dates with no slots, with a label customers see.</li><li><strong>Delivery zones.</strong> With <a href="https://plugins.craftcms.com/geomaps" target="_blank" rel="noreferrer">Geo Maps</a>, give each delivery area its own days, order limit and fee.</li><li><strong>Changes on a date.</strong> Close one window or change its limit for a single day, such as when a driver is away.</li><li><strong>Run sheet and packing list.</strong> Each day’s orders by slot, zone and suburb to print for drivers, and how many of each item to pack.</li><li><strong>Exports.</strong> Orders or the packing list as CSV for any date range, from the control panel or the command line.</li><li><strong>Staff can move orders.</strong> Change an order’s slot from the order page when a customer calls, even if it’s full, and email them the new time.</li><li><strong>Mark delivered.</strong> Tick orders off on the run sheet as drivers report back.</li><li><strong>At a glance.</strong> A dashboard widget, and a Delivery time column and Delivery date filter on Commerce’s orders.</li><li><strong>Add to calendar.</strong> A calendar file for confirmation emails.</li><li><strong>Payment check.</strong> Customers can’t pay without a slot, or with one that has filled up.</li></ul><h2 id="how-it-fits-into-commerce" tabindex="-1">How it fits into Commerce <a class="header-anchor" href="#how-it-fits-into-commerce" aria-label="Permalink to &quot;How it fits into Commerce&quot;">​</a></h2><p>Delivery Slots doesn’t replace Commerce’s shipping. Your shipping methods and rules still decide <strong>which</strong> methods an order can use and <strong>what they cost</strong>. Delivery Slots adds <strong>when</strong>:</p><ol><li>The customer enters their address and chooses a shipping method, as usual.</li><li>If that method has a schedule, your checkout shows its slots, from <code>cart.deliverySlotDays</code>.</li><li>The chosen slot posts with the cart form as <code>deliverySlot</code>, and is held for the cart.</li><li>When the order is paid, the slot is booked. It shows on the order and the run sheet.</li></ol><h2 id="who-delivers-the-orders" tabindex="-1">Who delivers the orders? <a class="header-anchor" href="#who-delivers-the-orders" aria-label="Permalink to &quot;Who delivers the orders?&quot;">​</a></h2><p>Your shop does, with its own drivers or a local courier you book. Delivery Slots doesn’t send drivers or connect to couriers: it decides which times customers can choose, keeps each slot to what you can deliver, and gives you the <a href="/guides/run-sheet">run sheet</a>, packing list and CSV exports to plan each run. Import the CSV into a routing app, or hand a printed page per slot to each driver.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/getting-started/installation">Install the plugin</a></li><li><a href="/getting-started/schedules">Set up a schedule</a></li><li><a href="/guides/slot-picker">Add the slot picker to your checkout</a></li></ul>',12)])])}const f=o(i,[["render",n]]);export{g as __pageData,f as default};
